package com.markethub.vendor.catalog.api;
import com.markethub.vendor.application.ApprovedVendorAccess; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.dao.OptimisticLockingFailureException; import java.math.BigDecimal; import java.time.Instant; import java.util.List; import java.util.UUID;
@Service public class VendorProductService {
 private final JdbcTemplate jdbc; private final ApprovedVendorAccess access; public VendorProductService(JdbcTemplate jdbc,ApprovedVendorAccess access){this.jdbc=jdbc;this.access=access;}
 public record ProductView(UUID id,String name,String slug,String description,BigDecimal price,String currency,String status,long version,Instant createdAt,Instant updatedAt){}
 public List<ProductView> list(UUID userId){UUID vendor=access.requireApprovedVendor(userId);return jdbc.query("select id,name,slug,description,price,currency,status,version,created_at,updated_at from products where vendor_id=? and status<>'ARCHIVED' order by created_at desc",(rs,n)->view(rs.getObject("id",UUID.class),rs.getString("name"),rs.getString("slug"),rs.getString("description"),rs.getBigDecimal("price"),rs.getString("currency"),rs.getString("status"),rs.getLong("version"),rs.getTimestamp("created_at").toInstant(),rs.getTimestamp("updated_at").toInstant()),vendor);}
 @Transactional public ProductView create(UUID userId,VendorProductRequest r){UUID vendor=access.requireApprovedVendor(userId),id=UUID.randomUUID();jdbc.update("insert into products(id,vendor_id,name,slug,description,price,currency,status,created_at,updated_at) values (?,?,?,?,?,?,?,'ACTIVE',now(),now())",id,vendor,r.name().trim(),r.slug(),r.description(),r.price(),r.currency());return find(vendor,id);}
 @Transactional public ProductView update(UUID userId,UUID productId,VendorProductRequest r){UUID vendor=access.requireApprovedVendor(userId);ProductView current=find(vendor,productId);int changed=jdbc.update("update products set name=?,slug=?,description=?,price=?,currency=?,updated_at=now(),version=version+1 where id=? and vendor_id=? and version=? and status<>'ARCHIVED'",r.name().trim(),r.slug(),r.description(),r.price(),r.currency(),productId,vendor,current.version());if(changed!=1)throw new OptimisticLockingFailureException("Product was changed concurrently or is archived");return find(vendor,productId);}
 @Transactional public void archive(UUID userId,UUID productId){UUID vendor=access.requireApprovedVendor(userId);int changed=jdbc.update("update products set status='ARCHIVED',archived_at=now(),updated_at=now(),version=version+1 where id=? and vendor_id=? and status<>'ARCHIVED'",productId,vendor);if(changed!=1)throw new IllegalArgumentException("Product not found or already archived");}
 private ProductView find(UUID vendor,UUID id){return jdbc.query("select id,name,slug,description,price,currency,status,version,created_at,updated_at from products where id=? and vendor_id=?",(rs,n)->view(rs.getObject("id",UUID.class),rs.getString("name"),rs.getString("slug"),rs.getString("description"),rs.getBigDecimal("price"),rs.getString("currency"),rs.getString("status"),rs.getLong("version"),rs.getTimestamp("created_at").toInstant(),rs.getTimestamp("updated_at").toInstant()),id,vendor).stream().findFirst().orElseThrow(()->new IllegalArgumentException("Product not found"));}
 private ProductView view(UUID id,String name,String slug,String description,BigDecimal price,String currency,String status,long version,Instant created,Instant updated){return new ProductView(id,name,slug,description,price,currency,status,version,created,updated);}
}